{"command":"@'
$ErrorActionPreference = 'Stop'
function Get-SkillMeta($root, $platform) {
  if (-not (Test-Path $root)) { return @() }
  Get-ChildItem -Path $root -Directory | ForEach-Object {
    $skillDir = $_.FullName
    $skillFile = Join-Path $skillDir 'SKILL.md'
    if (-not (Test-Path $skillFile)) { return }
    $raw = Get-Content -Raw $skillFile
    $name = if ($raw -match '(?ms)^---\s*.*?^name:\s*([^\r\n]+).*?^---') { $matches[1].Trim().Trim('"''') } else { '' }
    $desc = if ($raw -match '(?ms)^---\s*.*?^description:\s*([^\r\n]+).*?^---') { $matches[1].Trim().Trim('"''') } else { '' }
    $body = $raw -replace '(?ms)^---.*?^---\s*',''
    [pscustomobject]@{
      platform = $platform
      dir = $_.Name
      frontmatterName = $name
      description = $desc
      lines = ($raw -split "`n").Count
      words = ($body | Measure-Object -Word).Words
      hasUseWhen = $desc -match '^Use when'
      hasFrontmatter = $raw -match '^---'
      path = $skillFile
    }
  }
}
$all = @()
$all += Get-SkillMeta 'C:\Users\win\.claude\skills' 'claude'
$all += Get-SkillMeta 'C:\Users\win\.cursor\skills' 'cursor'
$all += Get-SkillMeta 'C:\Users\win\.codex\skills' 'codex'
$all += Get-SkillMeta 'C:\Users\win\.agents\skills' 'agents'
$all | ConvertTo-Json -Depth 3
'@ | python -","timeout_ms":30000}

{"command":"@'
from pathlib import Path
import hashlib, json
roots = {
    'claude': Path(r'C:\Users\win\.claude\skills'),
    'cursor': Path(r'C:\Users\win\.cursor\skills'),
    'codex': Path(r'C:\Users\win\.codex\skills'),
    'agents': Path(r'C:\Users\win\.agents\skills'),
}
out = {}
for name, root in roots.items():
    hashes = {}
    if root.exists():
        for d in sorted([p for p in root.iterdir() if p.is_dir()]):
            f = d / 'SKILL.md'
            if f.exists():
                hashes[d.name] = hashlib.sha256(f.read_bytes()).hexdigest()
    out[name] = hashes
print(json.dumps(out))
'@ | python -","timeout_ms":30000}

{"command":"$ErrorActionPreference = 'Stop'
function Get-SkillMeta($root, $platform) {
  if (-not (Test-Path $root)) { return @() }
  $items = @()
  Get-ChildItem -Path $root -Directory | ForEach-Object {
    $skillFile = Join-Path $_.FullName 'SKILL.md'
    if (-not (Test-Path $skillFile)) { return }
    $raw = Get-Content -Raw $skillFile
    $name = ''
    $desc = ''
    if ($raw -match '(?ms)^---\s*.*?^name:\s*([^\r\n]+).*?^---') { $name = $matches[1].Trim().Trim('"''') }
    if ($raw -match '(?ms)^---\s*.*?^description:\s*([^\r\n]+).*?^---') { $desc = $matches[1].Trim().Trim('"''') }
    $body = [regex]::Replace($raw, '(?ms)^---.*?^---\s*', '')
    $items += [pscustomobject]@{
      platform = $platform
      dir = $_.Name
      frontmatterName = $name
      description = $desc
      lines = ($raw -split "`n").Count
      bodyWords = ($body | Measure-Object -Word).Words
      hasUseWhen = $desc.StartsWith('Use when')
      path = $skillFile
    }
  }
  return $items
}
$all = @()
$all += Get-SkillMeta 'C:\Users\win\.claude\skills' 'claude'
$all += Get-SkillMeta 'C:\Users\win\.cursor\skills' 'cursor'
$all += Get-SkillMeta 'C:\Users\win\.codex\skills' 'codex'
$all += Get-SkillMeta 'C:\Users\win\.agents\skills' 'agents'
$all | ConvertTo-Json -Depth 3 -Compress","timeout_ms":30000}

