{"command":"$ErrorActionPreference = 'Stop'
$claudeRoot = 'C:\Users\win\.claude\skills'
$codexRoot = 'C:\Users\win\.codex\skills'
$claude = Get-ChildItem $claudeRoot -Directory | ForEach-Object {
  $f = Join-Path $_.FullName 'SKILL.md'; if (Test-Path $f) { [pscustomobject]@{name=$_.Name; hash=(Get-FileHash $f -Algorithm SHA256).Hash} }
}
$codex = Get-ChildItem $codexRoot -Directory | ForEach-Object {
  $f = Join-Path $_.FullName 'SKILL.md'; if (Test-Path $f) { [pscustomobject]@{name=$_.Name; hash=(Get-FileHash $f -Algorithm SHA256).Hash} }
}
$sharedNames = $claude.name | Where-Object { $_ -in $codex.name }
$diffs = foreach ($name in $sharedNames) {
  $ch = ($claude | Where-Object name -eq $name).hash
  $dh = ($codex | Where-Object name -eq $name).hash
  if ($ch -ne $dh) { [pscustomobject]@{name=$name; claudeHash=$ch; codexHash=$dh} }
}
$dupeHashes = $codex | Group-Object hash | Where-Object { $_.Count -gt 1 } | ForEach-Object { [pscustomobject]@{hash=$_.Name; names=($_.Group.name -join ', ')} }
[pscustomobject]@{
  sharedNameCount = $sharedNames.Count
  changedInCodex = $diffs
  duplicateHashGroups = $dupeHashes
} | ConvertTo-Json -Depth 5","timeout_ms":20000}

